// No loader, timer, animation loop or network requests. Uses an existing GLTFLoader scene.
export const POSES = Object.freeze(Object.fromEntries(Object.entries(CONTRACT.poses).map(([name, p]) => [name, Object.freeze(p)])));
export function bindRobot(scene) {
  const names = ['ROBOT_ROOT', 'ROBOT_RAIL_ANCHOR', 'ARM_SLIDE', 'VERTICAL_SLIDER', 'TOOL_FEED', 'TOOL_TCP'];
  const nodes = Object.fromEntries(names.map(name => {
    const object = scene.getObjectByName(name);
    if (!object) throw new Error('Missing R3 robot node: ' + name);
    return [name, object];
  }));
  function setPose(input) {
    const pose = typeof input === 'string' ? POSES[input] : input;
    if (!pose || typeof pose !== 'object') throw new Error('Unknown R3 pose');
    for (const [key, [min, max]] of Object.entries(CONTRACT.ranges)) {
      if (!Number.isFinite(pose[key]) || pose[key] < min || pose[key] > max)
        throw new RangeError(key + ' outside [' + min + ', ' + max + '] m');
    }
    nodes.ARM_SLIDE.position.z = -pose.extension;
    nodes.VERTICAL_SLIDER.position.y = CONTRACT.nodes.VERTICAL_SLIDER.base + pose.sliderOffset;
    nodes.TOOL_FEED.position.z = -pose.toolFeed;
    scene.updateMatrixWorld(true);
    return nodes.TOOL_TCP;
  }
  // Pure progress setter for the two described paths; caller owns timing.
  function setPathPose(segment, progress) {
    if (!Number.isInteger(segment) || segment < 0 || segment >= CONTRACT.sampled_path.length ||
        !Number.isFinite(progress) || progress < 0 || progress > 1)
      throw new RangeError('segment must be 0 or 1; progress must be within [0,1]');
    const [a, b] = CONTRACT.sampled_path[segment].map(name => POSES[name]);
    const p = Object.fromEntries(Object.keys(CONTRACT.ranges).map(k => [k, a[k] + (b[k] - a[k]) * progress]));
    return setPose(p);
  }
  return Object.freeze({ nodes: Object.freeze(nodes), poses: POSES, setPose, setPathPose });
}

